/**
 * Utilities for converting hierarchical data to ReactFlow format
 */

/**
 * Convert hierarchical containable data to ReactFlow nodes and edges
 */
export const convertToReactFlow = (hierarchicalData) => {
  console.log('dataConverter: Starting conversion with data:', hierarchicalData);
  const nodes = [];
  const edges = [];
  let nodeId = 1;
  
  const processContainer = (container, parentId = null, level = 0) => {
    const currentNodeId = `node-${nodeId++}`;
    
    // Create node
    const node = {
      id: currentNodeId,
      type: 'customNode',
      position: calculatePosition(level, nodes.filter(n => n.position.y === level * 150).length),
      data: {
        id: container.id,
        name: container.name,
        type: container.entityType,
        deploymentUnitType: container.deploymentUnitType,
        folderType: container.folderType,
        description: container.description,
        uuaa: container.uuaa,
        code: container.code,
        className: container.className,
        level: level,
        containerData: container // Keep original data for reference
      }
    };
    
    nodes.push(node);
    
    // Create edge from parent if exists
    if (parentId) {
      edges.push({
        id: `edge-${parentId}-${currentNodeId}`,
        source: parentId,
        target: currentNodeId,
        type: 'smoothstep',
        animated: false,
        style: { 
          stroke: getEdgeColor(container.entityType),
          strokeWidth: 2 
        }
      });
    }
    
    // Process children recursively
    if (container.children && container.children.length > 0) {
      container.children.forEach(child => {
        processContainer(child, currentNodeId, level + 1);
      });
    }
    
    return currentNodeId;
  };
  
  // Process all root containers
  hierarchicalData.forEach(container => {
    console.log('dataConverter: Processing container:', container);
    processContainer(container);
  });
  
  console.log('dataConverter: Final nodes:', nodes);
  console.log('dataConverter: Final edges:', edges);
  return { nodes, edges };
};

/**
 * Calculate position for automatic layout
 */
const calculatePosition = (level, indexAtLevel) => {
  const LEVEL_HEIGHT = 150;
  const NODE_WIDTH = 200;
  const HORIZONTAL_SPACING = 250;
  
  return {
    x: indexAtLevel * HORIZONTAL_SPACING,
    y: level * LEVEL_HEIGHT
  };
};

/**
 * Get color for edges based on container type
 */
const getEdgeColor = (entityType) => {
  switch (entityType) {
    case 'DeploymentUnit':
      return '#3b82f6'; // Blue
    case 'ComponentFolder':
      return '#10b981'; // Green
    default:
      return '#6b7280'; // Gray
  }
};

/**
 * Get node style based on container type
 */
export const getNodeStyle = (data) => {
  const isDeploymentUnit = data.type === 'DeploymentUnit';
  
  const baseStyle = {
    background: isDeploymentUnit ? '#dbeafe' : '#d1fae5',
    border: `2px solid ${isDeploymentUnit ? '#3b82f6' : '#10b981'}`,
    borderRadius: '8px',
    padding: '12px',
    minWidth: '180px',
    color: '#1f2937',
    fontSize: '14px',
    fontFamily: 'system-ui, -apple-system, sans-serif'
  };
  
  return baseStyle;
};

/**
 * Get display text for different types
 */
export const getTypeDisplayText = (data) => {
  if (data.type === 'DeploymentUnit') {
    return data.deploymentUnitType?.replace('_', '-') || 'DU';
  }
  if (data.type === 'ComponentFolder') {
    return data.folderType?.toLowerCase() || 'folder';
  }
  return data.type;
};
